import * as React from 'react';
import {Node,Node2D,Node3D,ColorRect,AnimationPlayer,AnimatedSprite2D,TileMapLayer,GridMap,NavigationRegion2D,NavigationRegion3D,NavigationAgent2D,NavigationAgent3D,useNodeRef,useProcess,usePhysicsProcess} from '@godot-js/react';
import {useResource,useDemo,ProjectScene} from '@playground/api';
const checks={library:false,sprite:false,tiles:false,grid:false,nav2:false,nav3:false};
function Timeline(){const library=useResource('motion','AnimationLibrary'),ref=useNodeRef<'AnimationPlayer'>(),started=React.useRef(false);useProcess(ref,{writes:['animationLibraries','playback']},c=>{if(started.current)return;checks.library=c.command<number>('addLibrary','',library)===0;c.command('play','move',-1,1,false);started.current=true;});return <AnimationPlayer ref={ref} engineOwned={['animationLibraries','playback']}/>;}
function Sprite(){const frames=useResource('frames','SpriteFrames'),ref=useNodeRef<'AnimatedSprite2D'>(),started=React.useRef(false);useProcess(ref,{writes:['animation','frame','frameProgress']},c=>{if(!started.current){c.command('play','default',1,false);started.current=true;}checks.sprite=c.command('isPlaying');});return <AnimatedSprite2D ref={ref} spriteFrames={frames} position={{x:128,y:160}} scale={{x:32,y:32}} engineOwned={['animation','frame','frameProgress']}/>;}
function Tiles(){const tiles=useResource('tiles','TileSet'),ref=useNodeRef<'TileMapLayer'>(),written=React.useRef(false);useProcess(ref,{writes:['cells']},c=>{if(!written.current){for(let x=0;x<8;x++)c.command('setCell',{x,y:0},0,{x:x%2,y:0},0);written.current=true;}checks.tiles=c.command('getCellSourceId',{x:0,y:0})===0;});return <TileMapLayer ref={ref} tileSet={tiles} position={{x:64,y:240}} scale={{x:32,y:32}} engineOwned={['cells']}/>;}
function Grid(){const library=useResource('grid','MeshLibrary'),ref=useNodeRef<'GridMap'>(),written=React.useRef(false);useProcess(ref,{writes:['cells']},c=>{if(!written.current){c.command('setCellItem',{x:0,y:0,z:0},0,0);written.current=true;}checks.grid=c.command('getCellItem',{x:0,y:0,z:0})===0;});return <GridMap ref={ref} meshLibrary={library} engineOwned={['cells']}/>;}
function Navigation(){const polygon=useResource('nav2','NavigationPolygon'),mesh=useResource('nav3','NavigationMesh'),r2=useNodeRef<'NavigationAgent2D'>(),r3=useNodeRef<'NavigationAgent3D'>(),ticks=React.useRef(0);usePhysicsProcess(r2,{},c=>{if(++ticks.current>4){const p=c.command<{x:number;y:number}>('getNextPathPosition');checks.nav2=Math.abs(p.x-2)<.01&&Math.abs(p.y-2)<.01;}});usePhysicsProcess(r3,{},c=>{if(ticks.current>4){const p=c.command<{x:number;y:number;z:number}>('getNextPathPosition');checks.nav3=Math.abs(p.x-2)<.01&&Math.abs(p.z-2)<.01;}});return <Node><NavigationRegion2D navigationPolygon={polygon}/><Node2D position={{x:1,y:1}}><NavigationAgent2D ref={r2} targetPosition={{x:2,y:2}} pathDesiredDistance={.01} targetDesiredDistance={.01}/></Node2D><NavigationRegion3D navigationMesh={mesh}/><Node3D position={{x:1,y:0,z:1}}><NavigationAgent3D ref={r3} targetPosition={{x:2,y:0,z:2}} pathDesiredDistance={.01} targetDesiredDistance={.01}/></Node3D></Node>;}
export default function App(){const ref=useNodeRef<'Node2D'>(),demo=useDemo(),background=useResource('background','ShaderMaterial');useProcess(ref,{},()=>demo.stats({kind:'resources',...checks,scene:true}));return <Node2D ref={ref}><ColorRect material={background} position={{x:0,y:0}} size={{x:960,y:640}} color={{r:.03,g:.06,b:.1,a:1}}/><Node2D name="Mover" engineOwned={['transform2d']}><ColorRect size={{x:32,y:32}} color={{r:.2,g:.8,b:1,a:1}}/></Node2D><Timeline/><Sprite/><Tiles/><Grid/><Navigation/><ProjectScene name="/assets/preview.tscn"/></Node2D>;}

